INSERT INTO `creature_text_locale` (`CreatureID`, `GroupID`, `ID`, `Locale`, `Text`) VALUES
(17264, 1, 0, 'koKR', 'Ty tam! Pilnuj dobrze tych wałów, intruzi mogą się zjawić w każdej chwili!'),
(17271, 1, 0, 'koKR', 'Tak jest! Nie zawiodę Spaczonej Hordy!'),
