INSERT INTO `broadcast_text_locale` (`ID`, `locale`, `MaleText`, `FemaleText`, `VerifiedBuild`) VALUES
(13981, 'koKR', 'Stawiliście czoła wielu wyzwaniom... Szkoda, że wszystko na próżno! Wkrótce wasz lud uklęknie przed MOIM panem!', '', 0),
(13999, 'koKR', 'Czujecie to? Jakimś cudem do naszej cytadeli wdarło się świeże mięso. Uważajcie na intruzów.', '', 0),
(14000, 'koKR', 'Intruzi! Zatrzymajcie ich, aż wypuszczę ogary wojenne!', '', 0),
(14001, 'koKR', 'Za późno, teraz poczujcie gniew moich ogarów wojennych!', '', 0),
(17498, 'koKR', 'Ulecz mnie, szybko!', '', 0),
(17499, 'koKR', 'Odsuń się, szczeniaku!', '', 0),
(17500, 'koKR', 'Pożegnaj się!', '', 0),
(17501, 'koKR', 'Zbyt łatwe.', '', 0),
(17502, 'koKR', 'Co my tu mamy?', '', 0),
(17503, 'koKR', 'To może trochę zaboleć...', '', 0),
(17504, 'koKR', 'Będę się tym rozkoszował...', '', 0),
(17630, 'koKR', 'To... jeszcze nie koniec.', '', 0),
(17631, 'koKR', 'Giń, słabeuszu!', '', 0),
(17632, 'koKR', 'Zwycięstwo jest moje!', '', 0),
(17633, 'koKR', 'Nie dam się pokonać!', '', 0),
(17634, 'koKR', 'Śmiesz stawać przeciwko MNIE?', '', 0),
(17635, 'koKR', 'Twoja zuchwałość będzie twoją śmiercią!', '', 0),
(17637, 'koKR', 'Achor she-ki! Ucztuj, mój pupilu! Najedz się do syta!', '', 0),
(18260, 'koKR', 'A-kreesh!', '', 0);
